  // catalog.js
  function normalizeActionList(raw) {
    const values = Array.isArray(raw) ? raw : [];
    const commands = [];
    values.forEach((item) => {
      const command = typeof item === "string" ? item : item?.RunEnum || item?.runEnum || item?.name || item?.cmd || item?.command;
      if (!command) return;
      const label = typeof item === "object" && item ? item.RunEnumText || item.runEnumText || item.label || item.title : "";
      const normalizedCommand = String(command);
      if (label) ACTION_LABELS[normalizedCommand] = String(label);
      const icon = typeof item === "object" && item ? item.RunEnumPic || item.runEnumPic || item.icon : "";
      if (icon) state.actionIcons[normalizedCommand] = String(icon);
      commands.push(normalizedCommand);
    });
    return [...new Set(commands)];
  }
  function actionLabel(command) {
    if (ACTION_LABELS[command]) return ACTION_LABELS[command];
    return command.replace(/_on$/i, "").replace(/_off$/i, "").replace(/_\d+$/i, "").replaceAll("_", " ").toLowerCase().replace(/^./, (letter) => letter.toUpperCase());
  }
  function levelGroup(id) {
    return LEVEL_GROUPS.find((group) => group.id === id);
  }
  function hasLevelGroup(group, available) {
    const levels = [group.off, `${group.id}_1`, `${group.id}_2`, `${group.id}_3`];
    return levels.some((command) => available.includes(command));
