:root {
  color-scheme: dark;
  /* Оформление карточек: общие значения для всех виджетов, слотов и плиток. Тема (style-themes.js) их переопределяет. */
  --card-bg: rgba(2, 6, 12, .94);
  --card-bg-soft: rgba(11, 22, 39, .92);
  --card-bg-base: rgba(17, 17, 20, .74);
  --card-bg-faint: rgba(2, 6, 12, .28);
  --card-border: rgba(255, 255, 255, .16);
  --card-border-top: rgba(255, 255, 255, .14);
  --safe-left: 0px;
  --safe-top: 0px;
  --safe-right: 0px;
  --safe-bottom: 0px;
  --bg: #071322;
  --wallpaper: none;
  --surface: var(--card-bg-soft);
  --surface-soft: rgba(150, 190, 240, .07);
  --line: rgba(150, 190, 240, .16);
  --text: #eaf2ff;
  --muted: #8aa0bd;
  --accent: #6fc3fa;
  --accent-rgb: 111, 195, 250;
  --blue: var(--accent);
  --hero-image: linear-gradient(135deg, #0b1d33 0%, #071322 50%, #0a1a2e 100%);
}

* { box-sizing: border-box; }
html, body { width: 100%; min-height: 100%; margin: 0; }
body { background-color: var(--bg); background-image: var(--hero-image); background-size: cover; background-position: center; background-repeat: no-repeat; background-attachment: fixed; color: var(--text); font-family: Inter, "Roboto", "Segoe UI", Arial, sans-serif; overscroll-behavior: none; -webkit-tap-highlight-color: transparent; position: relative; }
body::before { content: ""; position: fixed; inset: 0; pointer-events: none; background: linear-gradient(180deg, rgba(0, 0, 0, .2), transparent 42%), linear-gradient(0deg, rgba(6, 6, 8, .9), rgba(6, 6, 8, .18) 43%, transparent 68%); }
button, input { font: inherit; }
button { color: inherit; }

.dashboard { width: min(100%, 1920px); min-height: 100vh; margin: 0 auto; padding: calc(clamp(16px, 1.8vw, 30px) + var(--safe-top)) calc(clamp(16px, 1.8vw, 30px) + var(--safe-right)) calc(clamp(16px, 1.8vw, 30px) + var(--safe-bottom)) calc(clamp(16px, 1.8vw, 30px) + var(--safe-left)); display: grid; grid-template-rows: minmax(360px, 1fr) auto; gap: 12px; position: relative; }
.hero { min-height: 0; position: relative; overflow: visible; isolation: isolate; }
.hero-shade { position: absolute; inset: 0; z-index: -1; background: linear-gradient(180deg, rgba(0, 0, 0, .18), transparent 30%), linear-gradient(0deg, transparent 0%, rgba(0, 0, 0, .4) 26%, transparent 50%); }
.hero-clock { flex: 0 0 auto; min-width: 0; min-height: 168px; padding: 23px 26px; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; border: 1px solid var(--card-border); border-radius: 33px; background: var(--card-bg-base); backdrop-filter: blur(22px); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); }
.clock { font-size: clamp(48px, 5vw, 82px); font-weight: 350; line-height: .92; letter-spacing: -.065em; text-shadow: 0 3px 24px rgba(0, 0, 0, .45); }
.date { margin-top: 12px; font-size: 18px; text-shadow: 0 2px 12px rgba(0, 0, 0, .65); }
.date > span { display: block; }
.date > span + span { margin-top: 2px; }
.hero-bottom { position: absolute; left: 0; right: 0; bottom: 56px; display: flex; align-items: center; justify-content: center; gap: 26px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: none; }
.hero-bottom::-webkit-scrollbar { display: none; }
.weather-widget, .player-widget { border: 1px solid var(--card-border); border-radius: 33px; background: var(--card-bg-base); backdrop-filter: blur(22px); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); }
.eyebrow { color: var(--muted); font-size: 11px; font-weight: 760; letter-spacing: .15em; }
.hero-bottom .eyebrow { font-size: 17px; }

.weather-widget { flex: 0 0 250px; min-width: 0; min-height: 168px; padding: 23px 26px; display: flex; align-items: center; gap: 18px; position: relative; border: 1px solid var(--card-border); color: var(--text); cursor: pointer; text-align: left; }
.weather-widget:active { transform: scale(.97); }
.weather-icon { width: 69px; height: 69px; flex: 0 0 auto; border-radius: 21px; display: grid; place-items: center; background: rgba(var(--accent-rgb), .12); color: var(--blue); font-size: 38px; }
.weather-copy { min-width: 0; display: flex; flex-direction: column; gap: 5px; }
.weather-copy strong { font-size: 38px; font-weight: 560; line-height: 1; }
.weather-copy > span:last-child { max-width: 180px; color: var(--muted); font-size: 17px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.weather-refresh { position: absolute; right: 15px; top: 14px; color: var(--muted); font-size: 20px; }
.weather-widget.loading .weather-refresh { color: var(--accent); animation: weather-spin .9s linear infinite; }
@keyframes weather-spin { to { transform: rotate(360deg); } }

.player-widget { flex: 1 0 480px; min-width: 0; width: auto; max-width: 930px; min-height: 168px; padding: 21px; display: flex; align-items: center; gap: 24px; }
.album-art { width: 126px; height: 126px; flex: 0 0 auto; border-radius: 23px; display: grid; place-items: center; overflow: hidden; background: radial-gradient(circle at 68% 28%, var(--accent), transparent 28%), linear-gradient(145deg, #4c5045, #151517 68%); }
.album-art span { font-size: 33px; font-weight: 850; }
.album-art.has-image { background-size: cover; background-position: center; }
