#nav-strip { position: absolute; left: 23px; right: 23px; top: 112px; height: 64px; display: none; align-items: center; gap: 16px; padding: 0 22px; border-radius: 22px; background: rgba(2, 6, 12, .78); border: 1px solid rgba(255, 255, 255, .22); color: #eaf2ff; z-index: 3; font-size: 20px; }
