body.nav-mode.nav-quiet .hero-clock, body.nav-mode.nav-quiet #weather-widget, body.nav-mode.nav-quiet #player-stage { opacity: 0; pointer-events: none; transition: opacity .3s ease; }
body.nav-mode .hero-clock, body.nav-mode #weather-widget, body.nav-mode #player-stage { transition: opacity .3s ease; }

/* The progress fills glide between the 250 ms updates. */
