.cs-backdrop { position: absolute; inset: 0; background: #000a; }
.cs-panel { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(720px, calc(100vw - 32px)); max-height: calc(100vh - 48px); display: flex; flex-direction: column; border-radius: 22px; background: #0e1b27; color: #eaf2ff; border: 1px solid #ffffff26; box-shadow: 0 16px 40px #0009; }
