/* Variant C: the open player fills the screen. A blurred cover is the background, the cover is large, the controls are big,
   and a "back to home" button sits top left. Only on the classic home, not on the navigation screen. */
#player-backdrop { display: none; position: fixed; inset: -60px; z-index: 0; background: var(--cover-art, linear-gradient(135deg, #ff7a59, #8a3ffc)) center / cover no-repeat; filter: blur(60px) brightness(.5) saturate(120%); pointer-events: none; }
#player-back { display: none; position: fixed; left: 28px; top: 24px; z-index: 20; height: 52px; padding: 0 22px; align-items: center; border-radius: 26px; background: rgba(255, 255, 255, .16); border: 1px solid rgba(255, 255, 255, .26); color: #fff; font: 600 18px system-ui, sans-serif; cursor: pointer; }
