body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget { width: 240px; flex: 0 0 240px; height: 190px !important; min-height: 190px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded { width: auto !important; flex: 1 1 0 !important; min-width: 0 !important; height: 190px !important; flex-wrap: nowrap !important; justify-content: flex-start !important; row-gap: 0 !important; gap: 22px !important; padding: 17px 24px !important; box-sizing: border-box; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .album-art { width: 156px !important; height: 156px !important; flex: 0 0 156px !important; border-radius: 28px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .track-info { width: auto !important; flex: 1 1 0 !important; min-width: 0 !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .track-title { font-size: 22px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .track-artist { font-size: 16px !important; margin-bottom: 0 !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .track-progress.has-data { display: block !important; position: absolute !important; left: 210px !important; right: 24px !important; bottom: 14px !important; margin: 0 !important; height: 6px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls { order: 0 !important; flex: 0 0 auto !important; width: auto !important; gap: 18px !important; font-size: 30px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls .ui-ico { width: 40px !important; height: 40px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls .play { width: 64px !important; height: 64px !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls .play .ui-ico { width: 28px !important; height: 28px !important; }
body.player-expanded:not(.nav-mode) #player-playlists { position: fixed; top: 24px; right: 36px; z-index: 21; }
body.player-expanded:not(.nav-mode) #player-back { width: 52px; padding: 0; justify-content: center; font-size: 34px; line-height: 1; }
body.player-expanded:not(.nav-mode) #player-back { display: none; }

/* Reordering slots: the row must not start a horizontal scroll on touch, or the browser cancels the drag at once. */
body.slots-order .action-slots, body.slots-order .action-slot { touch-action: none; }

/* Home row: the clock, weather and player keep their own edges, so they do not merge into one glass strip. */
.hero-bottom > .hero-clock, .hero-bottom > .weather-widget, .hero-bottom > .player-widget { box-shadow: 0 0 0 1.5px rgba(255, 255, 255, .26), 0 10px 26px rgba(0, 0, 0, .35); }
:root[data-theme="light"] .hero-bottom > .hero-clock, :root[data-theme="light"] .hero-bottom > .weather-widget, :root[data-theme="light"] .hero-bottom > .player-widget { box-shadow: 0 0 0 1.5px rgba(20, 30, 45, .22), 0 10px 26px rgba(20, 30, 45, .14); }

/* Cover mode row: the same frames as on the home screen. */
body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget, body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .player-widget.expanded { box-shadow: 0 0 0 1.5px rgba(255, 255, 255, .26), 0 10px 26px rgba(0, 0, 0, .35); }
:root[data-theme="light"] body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, :root[data-theme="light"] body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget, :root[data-theme="light"] body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .player-widget.expanded { box-shadow: 0 0 0 1.5px rgba(20, 30, 45, .22), 0 10px 26px rgba(20, 30, 45, .14); }

/* Cover mode: the clock and the player get the same glass frame as the weather card (the earlier shadow alone did not show). */
body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .player-widget.expanded { background: rgba(255, 255, 255, .12) !important; border: 1px solid rgba(255, 255, 255, .26) !important; border-radius: 26px !important; box-shadow: 0 10px 26px rgba(0, 0, 0, .35) !important; box-sizing: border-box; }
:root[data-theme="light"] body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, :root[data-theme="light"] body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .player-widget.expanded { background: rgba(255, 255, 255, .55) !important; border: 1px solid rgba(20, 30, 45, .2) !important; box-shadow: 0 10px 26px rgba(20, 30, 45, .14) !important; }
body.player-expanded:not(.nav-mode) .actions-header, body.player-expanded:not(.nav-mode) .action-slots, body.player-expanded:not(.nav-mode) .app-drawer { display: none !important; }

/* Top notice for the trunk and window commands: the same place and look as the track notice. */
#top-notice { position: fixed; left: 50%; top: 18px; z-index: 1000; padding: 0 26px; height: 56px; display: flex; align-items: center; border-radius: 999px; background: #000; color: #fff; font-size: 20px; font-weight: 600; box-shadow: 0 10px 30px rgba(0, 0, 0, .45); transform: translate(-50%, -140%); opacity: 0; pointer-events: none; transition: transform .35s cubic-bezier(.2, .8, .2, 1), opacity .25s ease; white-space: nowrap; }
#top-notice.show { transform: translate(-50%, 0); opacity: 1; }
:root[data-theme="light"] #top-notice { background: #fff; color: #111827; box-shadow: 0 10px 30px rgba(20, 40, 70, .18); border: 1px solid rgba(20, 40, 70, .12); }

/* The radar strip takes the notice place at the top; a window or trunk notice shows just below it. */
body.radar-only #top-notice { top: 86px; }

/* Radar strip at the top: the radar pill sits in the middle of the strip. */
body.radar-only #nav-strip { justify-content: center; }
body.radar-only #nav-strip .ns-radar { margin-left: 0 !important; margin-right: 0 !important; }

/* Cover mode sizes: set by cover-edit.js through CSS variables on body (defaults match the cover layout). */
body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock { width: var(--cv-clock-w, 240px) !important; flex: 0 0 var(--cv-clock-w, 240px) !important; height: var(--cv-clock-h, 190px) !important; min-height: var(--cv-clock-h, 190px) !important; }
body.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget { width: var(--cv-weather-w, 240px) !important; flex: 0 0 var(--cv-weather-w, 240px) !important; height: var(--cv-weather-h, 190px) !important; min-height: var(--cv-weather-h, 190px) !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded { height: var(--cv-player-h, 190px) !important; flex: var(--cv-player-flex, 1 1 0) !important; }
body.player-expanded:not(.nav-mode) .player-widget.expanded .album-art { width: calc(var(--cv-player-h, 190px) - 34px) !important; height: calc(var(--cv-player-h, 190px) - 34px) !important; flex: 0 0 calc(var(--cv-player-h, 190px) - 34px) !important; }

/* Cover mode settings: open button under the row, bar while arranging, corner handles on the cards. */
#cover-edit-open { display: none; position: fixed; left: 50%; bottom: 20px; transform: translateX(-50%); z-index: 22; height: 44px; padding: 0 22px; border-radius: 22px; border: 1px solid rgba(255, 255, 255, .26); background: rgba(255, 255, 255, .16); color: #fff; font-size: 15px; font-weight: 700; cursor: pointer; }
body.player-expanded:not(.nav-mode) #cover-edit-open { display: block; }
body.cover-edit #cover-edit-open { display: none; }
#cover-edit-bar { display: none; position: fixed; left: 50%; bottom: 14px; transform: translateX(-50%); z-index: 22; align-items: center; gap: 10px; white-space: nowrap; }
body.cover-edit #cover-edit-bar { display: flex; }
#cover-edit-bar .cv-hint { font-size: 14px; color: #ffe9a6; margin-right: 6px; text-shadow: 0 2px 8px #000; }
#cover-edit-bar button { height: 44px; padding: 0 20px; border: 1px solid #ffffff75; border-radius: 22px; background: #14243ee8; color: #fff; font-size: 14px; font-weight: 700; }
#cover-edit-bar button[data-act="done"] { background: #d9e9fd; color: #202e40; border-color: #d9e9fd; }
.cv-resize { display: none; position: absolute; right: 9px; bottom: 9px; width: 26px; height: 26px; border-right: 3px solid #ffd84a; border-bottom: 3px solid #ffd84a; border-radius: 0 0 9px 0; cursor: nwse-resize; z-index: 4; touch-action: none; }
body.cover-edit .cv-resize { display: block; }
body.cover-edit.player-expanded:not(.nav-mode) .hero-bottom.in-stage > .hero-clock, body.cover-edit.player-expanded:not(.nav-mode) .hero-bottom.in-stage > #weather-widget, body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded { position: relative !important; outline: 2px dashed #ffd84a; outline-offset: 4px; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls { touch-action: none; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls button { cursor: grab; touch-action: none; }
body.cover-edit.player-expanded:not(.nav-mode) .player-widget.expanded .player-controls button.cv-dragging { outline: 2px solid #ffd84a; outline-offset: 4px; border-radius: 50%; }

/* Журнал поездок (trips.js): кнопка в окне состояния автомобиля и отдельный экран. */
#trips-open { height: 40px; padding: 0 16px; margin-right: 10px; border-radius: 20px; border: 1px solid var(--accent); background: transparent; color: var(--accent); font-size: 15px; font-weight: 700; letter-spacing: 0; text-transform: none; cursor: pointer; }
#trip-sheet { display: none; position: fixed; inset: 0; z-index: 51; }
body.trip-sheet-open #trip-sheet { display: block; }
.ts-backdrop { position: absolute; inset: 0; background: #000a; }
.ts-panel { position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%); width: min(1040px, calc(100vw - 32px)); height: min(600px, calc(100vh - 40px)); display: flex; flex-direction: column; border-radius: 22px; background: var(--bg); border: 1px solid var(--line); color: var(--text); overflow: hidden; }
.ts-head { display: flex; justify-content: space-between; align-items: center; padding: 14px 18px 10px 22px; font-size: 15px; letter-spacing: .14em; text-transform: uppercase; }
.ts-close { width: 40px; height: 40px; border-radius: 50%; border: 1px solid currentColor; background: transparent; color: inherit; font-size: 22px; line-height: 1; cursor: pointer; }
.ts-body { flex: 1; min-height: 0; display: grid; grid-template-columns: 290px 1fr; }
.ts-list { border-right: 1px solid var(--line); overflow-y: auto; padding: 8px 12px 12px; }
.ts-day { color: var(--muted); font-size: 12px; letter-spacing: .08em; text-transform: uppercase; margin: 12px 6px 6px; }
.ts-trip { display: block; width: 100%; text-align: left; background: var(--surface-soft); border: 1px solid var(--line); border-radius: 14px; padding: 11px 13px; margin-bottom: 9px; color: var(--text); cursor: pointer; }
.ts-trip.sel { border-color: var(--accent); }
.ts-trip b { font-size: 16px; font-weight: 700; }
.ts-trip span { display: block; color: var(--muted); font-size: 13px; margin-top: 3px; }
.ts-empty { color: var(--muted); font-size: 15px; padding: 18px 8px; }
.ts-detail { overflow-y: auto; padding: 14px 18px 16px; display: flex; flex-direction: column; gap: 14px; min-width: 0; }
.ts-tiles { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; }
.ts-tile { background: var(--surface-soft); border: 1px solid var(--line); border-radius: 14px; padding: 9px 11px; min-width: 0; }
.ts-tile small { display: block; color: var(--muted); font-size: 12px; }
.ts-tile b { font-size: 21px; }
.ts-tile em { font-style: normal; color: var(--muted); font-size: 12px; }
.ts-chart { flex: 1; min-height: 240px; background: var(--surface-soft); border: 1px solid var(--line); border-radius: 16px; padding: 10px 12px; }
.ts-chart svg { width: 100%; height: 100%; display: block; }
.ts-note { color: var(--muted); font-size: 12px; }

/* Свои виджеты (customwidgets.js): размер карточки задаёт customwidgets.js через --cw-h и --cw-w (без container units, их нет в старом WebView). */
.hw-card.hw-custom { display: flex; flex-direction: column; gap: calc(var(--cw-h, 171px) * 2.5 / 100); position: relative; border: 1px solid var(--card-border); border-radius: 33px; background: var(--card-bg); box-shadow: 0 18px 50px rgba(0, 0, 0, .28); padding: 23px 26px; }
.hw-cw-head { font-size: clamp(11px, calc(var(--cw-h, 171px) * 6.5 / 100), 16px); letter-spacing: .12em; text-transform: uppercase; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }
.hw-cw-grid { display: flex; flex-wrap: wrap; gap: calc(var(--cw-h, 171px) * 2.5 / 100) calc(var(--cw-w, 340px) * 2.5 / 100); align-content: center; justify-content: center; align-items: center; flex: 1; min-height: 0; overflow-y: auto; }
.hw-cw-tile { flex: 1 1 calc(var(--cw-w, 340px) * 30 / 100); min-width: 0; height: clamp(56px, calc(var(--cw-h, 171px) * 50 / 100), 120px); padding: 6px calc(var(--cw-w, 340px) * 3 / 100); display: flex; flex-direction: column-reverse; align-items: center; justify-content: center; text-align: center; gap: calc(var(--cw-h, 171px) * 4 / 100); border-radius: clamp(14px, calc(var(--cw-h, 171px) * 13 / 100), 26px); border: 0; background: none; color: var(--text); font-weight: 570; cursor: pointer; }
.hw-cw-tile:active { transform: scale(.97); }
.hw-cw-ico { flex: 0 0 auto; width: clamp(22px, calc(var(--cw-h, 171px) * 24 / 100), 48px); height: clamp(22px, calc(var(--cw-h, 171px) * 24 / 100), 48px); border-radius: 30%; display: inline-flex; align-items: center; justify-content: center; color: #79dcff; background: rgba(var(--accent-rgb), .15); }
.hw-cw-ico svg { width: 100%; height: 100%; }
.hw-cw-name { font-size: clamp(16px, calc(var(--cw-h, 171px) * 12 / 100), 22px); font-weight: 570; line-height: 1.16; max-width: 100%; text-align: center; overflow: hidden; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.hw-cw-val { flex: 1 1 calc(var(--cw-w, 340px) * 28 / 100); min-width: 0; padding: 0; background: none; border: 0; text-align: center; }
.hw-cw-val small { display: block; color: var(--muted); font-size: clamp(10px, calc(var(--cw-h, 171px) * 6 / 100), 13px); letter-spacing: .12em; text-transform: uppercase; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hw-cw-val b { font-weight: 600; font-size: clamp(18px, calc(var(--cw-h, 171px) * 30 / 100), 60px); line-height: 1.1; }
.hw-cw-val:only-child { flex-basis: 100%; }
.hw-cw-val:only-child b { font-size: clamp(22px, calc(var(--cw-h, 171px) * 42 / 100), 80px); }
.hw-cw-val em { font-style: normal; color: var(--muted); font-size: clamp(10px, calc(var(--cw-h, 171px) * 6 / 100), 13px); }
.hw-cw-del { display: none; position: absolute; top: 8px; right: 14px; z-index: 5; height: 32px; padding: 0 12px; border-radius: 16px; border: 1px solid #ff8a6b; background: #2a1410; color: #ffb3a3; font-size: 13px; font-weight: 700; cursor: pointer; }
body.hw-edit .hw-cw-del { display: block; }

/* Свои слоты (customslots.js): выбор иконки в редакторе; сами слоты в стиле кнопок климата. */
.cs-icons { display: grid; grid-template-columns: repeat(auto-fill, minmax(64px, 1fr)); gap: 8px; max-height: 200px; overflow-y: auto; padding: 2px; }
.cs-icon { height: 64px; padding: 0 6px; border-radius: 18px; border: 1px solid var(--line); background: var(--card-bg); color: #79dcff; display: grid; place-items: center; font-size: 13px; cursor: pointer; }
.cs-icon svg { width: 30px; height: 30px; }
.cs-icon[data-key=""] { color: var(--text); font-weight: 570; }
.cs-icon.on { border-color: var(--accent); box-shadow: 0 0 0 2px rgba(var(--accent-rgb), .45); }

/* Тема «Стекло» (style-themes.js): размытие карточек за их фоном. Стандартная тема эти правила не получает. */
html.theme-glass .action-slot, html.theme-glass .hero-clock, html.theme-glass #weather-widget, html.theme-glass .player-widget, html.theme-glass .hw-card, html.theme-glass .hw-custom {
  -webkit-backdrop-filter: blur(12px) saturate(125%); backdrop-filter: blur(12px) saturate(125%);
}
html.theme-tesla .action-slot, html.theme-tesla .hero-clock, html.theme-tesla #weather-widget, html.theme-tesla .player-widget, html.theme-tesla .hw-card, html.theme-tesla .hw-custom {
  -webkit-backdrop-filter: blur(18px) saturate(120%); backdrop-filter: blur(18px) saturate(120%);
}
/* Тема «StreletS27»: размытие 20 px, как у их карточек, и перекидные плитки часов (цифры — span.dg из clock.js). */
html.theme-strelets .action-slot, html.theme-strelets .hero-clock, html.theme-strelets #weather-widget, html.theme-strelets .player-widget, html.theme-strelets .hw-card, html.theme-strelets .hw-custom {
  -webkit-backdrop-filter: blur(20px); backdrop-filter: blur(20px);
}
.cw-editor { position: fixed; inset: 0; z-index: 60; background: #000a; display: flex; align-items: center; justify-content: center; }
.cw-editor-panel { width: min(760px, calc(100vw - 32px)); max-height: calc(100vh - 40px); overflow-y: auto; border-radius: 22px; background: var(--bg); border: 1px solid var(--line); color: var(--text); padding: 16px 20px 18px; display: flex; flex-direction: column; gap: 12px; }
.cw-editor-head { display: flex; justify-content: space-between; align-items: center; font-size: 15px; letter-spacing: .14em; text-transform: uppercase; }
.cw-x { width: 40px; height: 40px; border-radius: 50%; border: 1px solid currentColor; background: transparent; color: inherit; font-size: 22px; cursor: pointer; }
.cw-field { display: flex; flex-direction: column; gap: 6px; font-size: 14px; color: var(--muted); }
.cw-field input { height: 42px; border-radius: 12px; border: 1px solid var(--line); background: var(--surface-soft); color: var(--text); padding: 0 12px; font-size: 16px; }
.cw-cols { display: grid; grid-template-columns: 1.4fr 1fr; gap: 16px; }
.cw-sub { margin: 0 0 6px; color: var(--muted); font-size: 13px; letter-spacing: .08em; text-transform: uppercase; }
.cw-list { max-height: 300px; overflow-y: auto; display: flex; flex-direction: column; gap: 2px; }
.cw-search { width: 100%; height: 38px; margin: 0 0 8px; border-radius: 12px; border: 1px solid var(--line); background: var(--surface-soft); color: var(--text); padding: 0 12px; font-size: 15px; }
.cw-check { display: flex; align-items: center; gap: 8px; padding: 6px 4px; font-size: 15px; }
.cw-check input { width: 18px; height: 18px; }
.cw-note { margin: 0; min-height: 18px; color: #ffb36b; font-size: 14px; }
.cw-actions { display: flex; justify-content: flex-end; }
.cw-actions button { height: 44px; padding: 0 22px; border-radius: 22px; border: none; background: var(--accent); color: #06101c; font-size: 16px; font-weight: 700; cursor: pointer; }
